  let c010 = ps_hash(i + vec3<f32>(0.0, 1.0, 0.0));
  let c110 = ps_hash(i + vec3<f32>(1.0, 1.0, 0.0));
  let c001 = ps_hash(i + vec3<f32>(0.0, 0.0, 1.0));
  let c101 = ps_hash(i + vec3<f32>(1.0, 0.0, 1.0));
  let c011 = ps_hash(i + vec3<f32>(0.0, 1.0, 1.0));
